from __future__ import annotations
from typing import TYPE_CHECKING, List, Optional, Callable, Any

from app.models import Record, Batch  # circular import — models imports DataPipeline

PIPELINE_VERSION = '2.3.1'
DEFAULT_BATCH_SIZE = 100
MAX_RETRIES = 3

class DataPipeline:
    '''Core data processing pipeline.

    Processes Record objects through a series of transformation stages.
    Each stage is a callable that takes a Record and returns a transformed Record.
    '''

    def __init__(self, name: str, stages: Optional[List[Callable]] = None, batch_size: int = DEFAULT_BATCH_SIZE):
        self.name = name
        self.stages = stages or []
        self.batch_size = batch_size
        self._results: List[Any] = []
        self._errors: List[dict] = []
        self._stats = {'processed': 0, 'failed': 0, 'skipped': 0, 'total_batches': 0}

    def add_stage(self, func: Callable) -> 'DataPipeline':
        self.stages.append(func)
        return self

    def run(self, records: List['Record']) -> List[Any]:
        self._results = []
        self._errors = []
        for record in records:
            try:
                result = record
                for stage in self.stages:
                    result = stage(result)
                self._results.append(result)
                self._stats['processed'] += 1
            except Exception as e:
                self._errors.append({'record_id': record.id, 'error': str(e)})
                self._stats['failed'] += 1
        return self._results

    def get_stats(self) -> dict:
        return dict(self._stats)

    def get_errors(self) -> List[dict]:
        return list(self._errors)

    def reset(self) -> None:
        self._results = []
        self._errors = []
        self._stats = {'processed': 0, 'failed': 0, 'skipped': 0, 'total_batches': 0}

