from __future__ import annotations
import datetime
from typing import Optional, List, Dict, Any
from dataclasses import dataclass, field
from app.pipeline import DataPipeline  # circular import — pipeline imports Record

RECORD_STATUSES = ('pending', 'processing', 'completed', 'failed', 'skipped')

@dataclass
class Record:
    id: int
    name: str
    created_at: datetime.datetime = field(default_factory=datetime.datetime.utcnow)
    updated_at: Optional[datetime.datetime] = None
    status: str = 'pending'
    priority: int = 0
    tags: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if self.status not in RECORD_STATUSES:
            raise ValueError(f'Invalid status {self.status!r}')

    def to_dict(self) -> dict:
        return {'id': self.id, 'name': self.name, 'status': self.status,
                'priority': self.priority, 'tags': list(self.tags),
                'metadata': dict(self.metadata)}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'Record':
        return cls(id=data['id'], name=data['name'],
                   status=data.get('status', 'pending'),
                   priority=data.get('priority', 0),
                   tags=list(data.get('tags', [])),
                   metadata=dict(data.get('metadata', {})))

@dataclass
class Batch:
    id: int
    records: List[Record] = field(default_factory=list)
    pipeline: Optional[DataPipeline] = None
    created_at: datetime.datetime = field(default_factory=datetime.datetime.utcnow)
    max_size: int = 500

    def add_record(self, record: Record) -> None:
        if len(self.records) >= self.max_size:
            raise OverflowError(f'Batch {self.id} is full (max_size={self.max_size})')
        self.records.append(record)

    def process(self) -> List[Any]:
        if self.pipeline is None:
            raise RuntimeError(f'No pipeline attached to batch {self.id}')
        return self.pipeline.run(self.records)

    def size(self) -> int:
        return len(self.records)

