from __future__ import annotations
from typing import List, Optional, Callable
from app.models import Record  # safe — models will no longer import pipeline at module level
from app.pipeline import DataPipeline  # indirect circular: utils -> pipeline -> models -> (was pipeline)

VALID_PRIORITIES = range(0, 11)

def validate_record(record: Record) -> bool:
    if not isinstance(record.id, int) or record.id < 0:
        return False
    if not record.name or not isinstance(record.name, str):
        return False
    if record.priority not in VALID_PRIORITIES:
        return False
    return True

def build_pipeline(name: str, stages: Optional[List[Callable]] = None) -> DataPipeline:
    pipeline = DataPipeline(name=name, stages=stages or [])
    return pipeline

def filter_records(records: List[Record], status: str) -> List[Record]:
    return [r for r in records if r.status == status]

def sort_records(records: List[Record], key: str = 'priority') -> List[Record]:
    return sorted(records, key=lambda r: getattr(r, key, 0), reverse=True)

def batch_records(records: List[Record], batch_size: int = 100) -> List[List[Record]]:
    return [records[i:i + batch_size] for i in range(0, len(records), batch_size)]

